      SUBROUTINE VRBGETCC     GET PARAMETERS DESCRIBING VERNIER MAGNETCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'INDPAR.CIN'C      INTEGER         IADR, IANG, IB, IDATA, IK, IL, IT      INTEGER         NANG35, NB35, NK35, NL35      REAL            DATAR      EXTERNAL        DATAR, IDATACC     MAGNET LENGTHC      NL35 = 1      NB35 = 2      NANG35 = 3      NK35 = 4      IL = IPTOJ(NL35)      IF (IL .NE. 0) THEN        IADR = I + 1        LBEND = DATAR(IADR)*UNITI(8)      ELSE        LBEND = 0.0      ENDIFCC     INDICES FOR OTHER PARAMETERSC      IB = IPTOJ(NB35)      IANG = IPTOJ(NANG35)      IK = IPTOJ(NK35)      IF (IK .NE. 0) GO TO 15      IF (IANG .NE. 0) GO TO 10      IF (IB .NE. 0) GO TO 5      B = 0.0      AL = 0.0      H0 = 0.0      GO TO 20CC     MAGNETIC FIELDC    5 IADR = I + IB      B = DATAR(IADR)      B = B*UNITI(9)*RI/PREF      H0 = B/RI      AL = H0*LBEND      GO TO 20CC     BENDING ANGLEC   10 IADR = I + IANG      AL = DATAR(IADR)      AL = AL*UNITI(7)      IF (LBEND .NE. 0.0) THEN        H0 = AL/LBEND      ELSE        H0 = 0.0      ENDIF      B = RI*H0      GO TO 20CC     KICKC   15 IADR = I + IK      AL = - DATAR(IADR)      AL = AL*UNITI(7)      IF (LBEND .NE. 0.0) THEN        H0 = AL/LBEND      ELSE        H0 = 0.0      ENDIF      B = RI*H0CC     NORMALIZED FIELD DERIVATIVE (ASSUMED ZERO)C   20 NB = 0.0C      IT = IPTOJ(6)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END